        }

        using var context = CreateContext();

        var result = await BlogQueries.PopularTitles(context, 0, CancellationToken.None);

        Assert.Equal(new[] { "Top", "Bottom", "Mid" }, result);
    }

    [Fact]
    public async Task PopularTitles_NoPostExceedsMinViews_ReturnsEmptyList()
    {
        using (var seed = CreateContext())
        {
            Seed(seed, ("A", 1), ("B", 2));
        }

        using var context = CreateContext();

        var result = await BlogQueries.PopularTitles(context, 2, CancellationToken.None);

        Assert.Empty(result);
    }

    [Fact]
    public async Task PopularTitles_ReturnsTitlesAcrossMultipleBlogs()
    {
        using (var seed = CreateContext())
        {
            var first = NewBlog("First");
            var second = NewBlog("Second");
            seed.Blogs.AddRange(first, second);
            seed.SaveChanges();
            seed.Posts.Add(new Post { Title = "FirstPost", Views = 30, BlogId = first.Id });
            seed.Posts.Add(new Post { Title = "SecondPost", Views = 90, BlogId = second.Id });
            seed.SaveChanges();
        }

        using var context = CreateContext();

        var result = await BlogQueries.PopularTitles(context, 10, CancellationToken.None);

        Assert.Equal(new[] { "SecondPost", "FirstPost" }, result);
    }

    [Fact]
    public async Task PopularTitles_ThrowsOperationCanceledException_WhenCancelled()
    {
        using (var seed = CreateContext())
        {
            Seed(seed, ("A", 1));
        }

        using var context = CreateContext();
        using var cts = new CancellationTokenSource();
        cts.Cancel();

        await Assert.ThrowsAnyAsync<OperationCanceledException>(
            () => BlogQueries.PopularTitles(context, 0, cts.Token));
    }
}
