public class BlogQueriesPopularTitlesTests : IDisposable
{
    private readonly SqliteBlogDatabase _database = new();

    private BlogContext Context => _database.Context;

    public void Dispose() => _database.Dispose();

    private Blog AddBlog(string name)
    {
        var blog = new Blog { Name = name };
        Context.Blogs.Add(blog);
        Context.SaveChanges();
        return blog;
    }

    private void AddPost(Blog blog, string title, int views)
    {
        Context.Posts.Add(new Post { Title = title, Views = views, BlogId = blog.Id });
        Context.SaveChanges();
    }

    [Fact]
    public async Task PopularTitles_ReturnsOnlyTitlesWithViewsAboveThreshold()
    {
        var blog = AddBlog("Main");
        AddPost(blog, "Low", 5);
        AddPost(blog, "Mid", 10);
        AddPost(blog, "High", 20);

        var titles = await BlogQueries.PopularTitles(Context, 7, CancellationToken.None);

        Assert.Equal(new[] { "High", "Mid" }, titles);
    }

    [Fact]
    public async Task PopularTitles_ExcludesPostsWithViewsEqualToThreshold()
    {
        var blog = AddBlog("Main");
        AddPost(blog, "Equal", 10);
        AddPost(blog, "Above", 11);

        var titles = await BlogQueries.PopularTitles(Context, 10, CancellationToken.None);

        Assert.Equal(new[] { "Above" }, titles);
    }

    [Fact]
    public async Task PopularTitles_OrdersByViewsDescending()
    {
        var blog = AddBlog("Main");
        AddPost(blog, "Third", 3);
        AddPost(blog, "First", 9);
        AddPost(blog, "Second", 6);

        var titles = await BlogQueries.PopularTitles(Context, 0, CancellationToken.None);

        Assert.Equal(new[] { "First", "Second", "Third" }, titles);
    }

    [Fact]
    public async Task PopularTitles_IncludesPostsFromAllBlogs()
    {
        var first = AddBlog("First");
        var second = AddBlog("Second");
        AddPost(first, "FirstBlogPost", 8);
        AddPost(second, "SecondBlogPost", 12);

        var titles = await BlogQueries.PopularTitles(Context, 5, CancellationToken.None);

        Assert.Equal(new[] { "SecondBlogPost", "FirstBlogPost" }, titles);
    }

    [Fact]
    public async Task PopularTitles_ReturnsEmptyListWhenNoPostsQualify()
    {
        var blog = AddBlog("Main");
        AddPost(blog, "Quiet", 1);

        var titles = await BlogQueries.PopularTitles(Context, 5, CancellationToken.None);

        Assert.Empty(titles);
    }

    [Fact]
    public async Task PopularTitles_ReturnsEmptyListWhenDatabaseHasNoPosts()
    {
        AddBlog("Main");

        var titles = await BlogQueries.PopularTitles(Context, 0, CancellationToken.None);

        Assert.Empty(titles);
    }

    [Fact]
    public async Task PopularTitles_ThrowsWhenCancellationIsRequested()
    {
        var blog = AddBlog("Main");
        AddPost(blog, "Post", 10);
        using var cts = new CancellationTokenSource();
        cts.Cancel();

        await Assert.ThrowsAnyAsync<OperationCanceledException>(
            () => BlogQueries.PopularTitles(Context, 0, cts.Token));
    }
}
