using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using EfFixtures;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;
using Xunit;

public class BlogQueriesPopularTitlesTests : IDisposable
{
    private readonly SqliteConnection _connection;
    private readonly BlogContext _context;

    public BlogQueriesPopularTitlesTests()
    {
        _connection = new SqliteConnection("DataSource=:memory:");
        _connection.Open();

        var options = new DbContextOptionsBuilder<BlogContext>()
            .UseSqlite(_connection)
            .Options;

        _context = new BlogContext(options);
        _context.Database.EnsureCreated();
    }

    public void Dispose()
    {
        _context.Dispose();
        _connection.Dispose();
    }

    private static Blog NewBlog(int id, string name) => new Blog { Id = id, Name = name };

    private static Post NewPost(int id, string title, int views, Blog blog) =>
        new Post { Id = id, Title = title, Views = views, BlogId = blog.Id, Blog = blog };

    private void Seed(params Post[] posts)
    {
        var blogs = posts.Select(p => p.Blog).DistinctBy(b => b.Id).ToList();
        _context.Blogs.AddRange(blogs);
        _context.Posts.AddRange(posts);
        _context.SaveChanges();
    }

    [Fact]
    public async Task PopularTitles_ReturnsEmpty_WhenNoPosts()
    {
        var result = await BlogQueries.PopularTitles(_context, 0, CancellationToken.None);

        Assert.Empty(result);
    }

    [Fact]
    public async Task PopularTitles_ReturnsEmpty_WhenNoPostExceedsMinViews()
    {
        var blog = NewBlog(1, "Tech");
        Seed(NewPost(1, "Alpha", 5, blog), NewPost(2, "Beta", 10, blog));

        var result = await BlogQueries.PopularTitles(_context, 10, CancellationToken.None);

        Assert.Empty(result);
    }

    [Fact]
    public async Task PopularTitles_ExcludesPostWithViewsEqualToMinViews()
    {
        var blog = NewBlog(1, "Tech");
        Seed(NewPost(1, "Exactly", 10, blog), NewPost(2, "Above", 11, blog));

        var result = await BlogQueries.PopularTitles(_context, 10, CancellationToken.None);

        Assert.Equal(new List<string> { "Above" }, result);
    }

    [Fact]
    public async Task PopularTitles_ReturnsTitlesOrderedByViewsDescending()
    {
        var blog = NewBlog(1, "Tech");
        Seed(
            NewPost(1, "Low", 20, blog),
            NewPost(2, "High", 300, blog),
            NewPost(3, "Mid", 100, blog));

        var result = await BlogQueries.PopularTitles(_context, 0, CancellationToken.None);

        Assert.Equal(new List<string> { "High", "Mid", "Low" }, result);
    }

    [Fact]
    public async Task PopularTitles_IncludesPostsFromAllBlogs()
    {
        var tech = NewBlog(1, "Tech");
        var cooking = NewBlog(2, "Cooking");
        Seed(
            NewPost(1, "Tech Post", 50, tech),
            NewPost(2, "Recipe", 80, cooking),
            NewPost(3, "Quiet", 1, cooking));

        var result = await BlogQueries.PopularTitles(_context, 10, CancellationToken.None);

        Assert.Equal(new List<string> { "Recipe", "Tech Post" }, result);
    }

    [Fact]
    public async Task PopularTitles_ReturnsOnlyTitles()
    {
        var blog = NewBlog(1, "Tech");
        Seed(NewPost(1, "Only Title", 42, blog));

        var result = await BlogQueries.PopularTitles(_context, 0, CancellationToken.None);

        var title = Assert.Single(result);
        Assert.Equal("Only Title", title);
    }

    [Fact]
    public async Task PopularTitles_ThrowsOperationCanceledException_WhenCancelled()
    {
        var blog = NewBlog(1, "Tech");
        Seed(NewPost(1, "Alpha", 5, blog));
        using var cts = new CancellationTokenSource();
        cts.Cancel();

        await Assert.ThrowsAnyAsync<OperationCanceledException>(
            () => BlogQueries.PopularTitles(_context, 0, cts.Token));
    }
}
