        Assert.Equal(3, result.Count);
        Assert.Equal("Alpha", result[0].BlogName);
        Assert.Equal(101, result[0].TotalViews);
        Assert.Equal("Mid", result[1].BlogName);
        Assert.Equal(3, result[1].TotalViews);
        Assert.Equal("Zeta", result[2].BlogName);
        Assert.Equal(12, result[2].TotalViews);
    }

