        _connection = new SqliteConnection("DataSource=:memory:");
        _connection.Open();

        var options = new DbContextOptionsBuilder<BlogContext>()
            .UseSqlite(_connection)
            .Options;

        _context = new BlogContext(options);
        _context.Database.EnsureCreated();

        Seed();
    }

    private void Seed()
    {
        var alpha = new Blog { Name = "Alpha", Posts = new List<Post>(), Contributors = new List<Contributor>() };
        var beta = new Blog { Name = "Beta", Posts = new List<Post>(), Contributors = new List<Contributor>() };
        var gamma = new Blog { Name = "Gamma", Posts = new List<Post>(), Contributors = new List<Contributor>() };

        alpha.Posts.Add(new Post { Title = "Alpha Post 1", Views = 10 });
        alpha.Posts.Add(new Post { Title = "Alpha Post 2", Views = 5 });
        beta.Posts.Add(new Post { Title = "Beta Post 1", Views = 42 });
        beta.Posts.Add(new Post { Title = "Beta Post 2", Views = 8 });
        beta.Posts.Add(new Post { Title = "Beta Post 3", Views = 0 });

        _context.Blogs.AddRange(alpha, beta, gamma);
        _context.SaveChanges();
    }

    [Fact]
    public async Task TotalViewsPerBlog_SumsViewsForEachBlog()
    {
        var result = await BlogQueries.TotalViewsPerBlog(_context, CancellationToken.None);

        var alpha = Assert.Single(result, t => t.BlogName == "Alpha");
        Assert.Equal(15, alpha.TotalViews);

        var beta = Assert.Single(result, t => t.BlogName == "Beta");
        Assert.Equal(50, beta.TotalViews);
    }

    [Fact]
    public async Task TotalViewsPerBlog_ReturnsResultsOrderedByBlogName()
    {
        var result = await BlogQueries.TotalViewsPerBlog(_context, CancellationToken.None);

        Assert.Equal(new[] { "Alpha", "Beta", "Gamma" }, result.Select(t => t.BlogName));
    }

    [Fact]
    public async Task TotalViewsPerBlog_IncludesBlogWithNoPosts()
    {
        var result = await BlogQueries.TotalViewsPerBlog(_context, CancellationToken.None);

        var gamma = Assert.Single(result, t => t.BlogName == "Gamma");
        Assert.Equal(0, gamma.TotalViews);
    }

    [Fact]
    public async Task TotalViewsPerBlog_ReturnsEmptyList_WhenNoBlogs()
    {
        var options = new DbContextOptionsBuilder<BlogContext>()
            .UseSqlite(_connection)
            .Options;

        using (var emptyContext = new BlogContext(options))
        {
            emptyContext.Blogs.RemoveRange(emptyContext.Blogs.ToList());
            emptyContext.SaveChanges();

            var result = await BlogQueries.TotalViewsPerBlog(emptyContext, CancellationToken.None);
            Assert.Empty(result);
        }
    }

    [Fact]
    public async Task TotalViewsPerBlog_OnlyCountsPostsBelongingToEachBlog()
    {
        var strayBlog = new Blog { Name = "Zeta", Posts = new List<Post>(), Contributors = new List<Contributor>() };
        strayBlog.Posts.Add(new Post { Title = "Zeta Post", Views = 7 });

        _context.Blogs.Add(strayBlog);
        _context.SaveChanges();

        var result = await BlogQueries.TotalViewsPerBlog(_context, CancellationToken.None);

        var alpha = Assert.Single(result, t => t.BlogName == "Alpha");
        Assert.Equal(15, alpha.TotalViews);

        var zeta = Assert.Single(result, t => t.BlogName == "Zeta");
        Assert.Equal(7, zeta.TotalViews);
    }

    public void Dispose()
    {
        _context.Dispose();
        _connection.Dispose();
    }
}
